insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('food-01', 'food', 'Feijoada', 'Médio', '200 min', '15 porções', null, '["1 kg de feijão-preto (de molho)", "Lombo, costelinha, bacon, linguiça calabresa, paio e carne-seca", "Pé, rabo e orelha de porco dessalgados", "Cebola, alho, louro e salsinha", "Meia laranja com casca"]'::jsonb, '["Deixe o feijão de molho e dessalgue as carnes salgadas.", "Doure lombo e costelinha, depois o bacon, e refogue cebola, alho e louro.", "Junte o feijão e as carnes mais duras, cubra com água e cozinhe em fogo baixo por cerca de 3 h, retirando a espuma.", "Acrescente a laranja com casca, a salsinha e, no fim, linguiça e paio.", "Ajuste o sal e sirva com arroz, couve e farofa."]'::jsonb, false, 'at68bKulDWs', null, 'https://www.receiteria.com.br/receita/feijoada/', null)
