insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('food-02', 'food', 'Bolo de cenoura fofinho', 'Fácil', '60 min', '10 porções', null, '["3 ovos", "1/2 xícara de óleo", "1/2 xícara de leite", "260 g de cenoura", "300 g de açúcar", "280 g de farinha de trigo", "1 pitada de sal", "1 colher de sopa de fermento", "Cobertura de brigadeiro"]'::jsonb, '["Bata no liquidificador ovos, óleo, leite, açúcar e cenoura.", "Misture esse creme à farinha peneirada com o sal.", "Junte o fermento por último.", "Asse em forma untada a 180 °C até dourar.", "Cubra com brigadeiro depois de frio."]'::jsonb, false, '9_5L4s5O_QU', null, 'https://www.receiteria.com.br/receita/bolo-de-cenoura-fofinho/', null)
