insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('food-03', 'food', 'Frango assado com batatas', 'Fácil', '95 min', '4 porções', null, '["1 kg de sobrecoxas", "500 g de batatas", "1/2 xícara de maionese", "1/2 colher de sopa de alho", "Sal, pimenta e 1 colher de chá de orégano", "2 colheres de sopa de salsinha", "Manteiga para untar"]'::jsonb, '["Descasque as batatas e corte cada uma em 4.", "Misture alho, sal, pimenta, orégano, maionese e salsinha.", "Envolva frango e batatas no tempero.", "Distribua em forma untada.", "Asse a 180 °C por cerca de 1h20, até dourar."]'::jsonb, false, null, null, 'https://www.receiteria.com.br/receita/frango-assado-com-batatas/', null)
