insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('food-04', 'food', 'Arroz carreteiro', 'Fácil', '50 min', '5 porções', null, '["2 xícaras de arroz", "4 xícaras de água quente", "100 g de carne-seca dessalgada e desfiada", "250 g de linguiça calabresa", "70 g de bacon", "1/2 cebola, 2 dentes de alho, 2 folhas de louro", "Salsinha, pimenta e limão"]'::jsonb, '["Aqueça a água em fogo baixo.", "Frite bacon e calabresa; refogue cebola e alho.", "Junte carne-seca, louro e arroz.", "Adicione a água quente e cozinhe semitampado por cerca de 20 min.", "Descanse tampado por 5 min e finalize com salsinha."]'::jsonb, false, '6xHCvH4sKbA', null, 'https://www.receiteria.com.br/receita/arroz-carreteiro/', null)
