insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('food-05', 'food', 'Sopa de legumes com macarrão', 'Fácil', '45 min', '6 porções', null, '["140 g de macarrão ave maria", "2 colheres de sopa de azeite", "1 cebola, 1/2 pimentão, 4 dentes de alho", "2 L de água ou caldo de legumes", "1 cenoura, 5 batatas, 4 mandioquinhas", "Sal, pimenta, páprica e cheiro-verde"]'::jsonb, '["Refogue pimentão, cebola e alho no azeite.", "Junte a cenoura e a água e tempere.", "Acrescente batatas e mandioquinha com intervalos de uns 5 min.", "Adicione o macarrão e cozinhe pelo tempo da embalagem.", "Acerte o sal e finalize com cheiro-verde."]'::jsonb, false, 'AcO1Iv227xY', null, 'https://www.receiteria.com.br/receita/sopa-de-legumes/', null)
