insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('food-06', 'food', 'Macarrão alho e óleo', 'Fácil', '10 min', '2 porções', null, '["250 g de espaguete", "2 dentes de alho", "Azeite a gosto", "1 colher de sopa de manteiga", "Sal, pimenta-do-reino e cebolinha"]'::jsonb, '["Amasse o alho com sal.", "Cozinhe o espaguete al dente em água salgada.", "Doure o alho no azeite com a manteiga, sem queimar.", "Junte a massa e mexa, com um pouco da água do cozimento.", "Finalize com cebolinha e um fio de azeite."]'::jsonb, false, 'iMTdsbzsFCc', null, 'https://www.receiteria.com.br/receita/macarrao-alho-e-oleo/', null)
