insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('food-07', 'food', 'Moqueca de peixe simples', 'Médio', '45 min', 'Não informado', null, '["400 g de filé de badejo ou pescada amarela", "3 pimentões (verde, vermelho, amarelo)", "1 cebola, 2 tomates, 1 limão", "200 ml de leite de coco", "2 colheres de sopa de azeite de dendê", "3 colheres de sopa de azeite", "Coentro, cebolinha, alho e pimenta dedo-de-moça"]'::jsonb, '["Pique os legumes e as ervas.", "Refogue cebola e pimentões no azeite; junte alho, pimenta e tomate.", "Tempere o peixe com limão e sal e coloque sobre o refogado.", "Adicione leite de coco, dendê e coentro e deixe ferver.", "Tampe e cozinhe em fogo baixo por uns 5 min; sirva com arroz e farofa."]'::jsonb, false, null, null, 'https://www.receiteria.com.br/receita/moqueca-de-peixe-simples/', null)
