insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('food-08', 'food', 'Pudim de leite condensado', 'Médio', '75 min + 2 h de geladeira', '6 a 8 porções', null, '["Calda: 1 xícara de açúcar e 1/2 xícara de água quente", "3 ovos", "320 ml de leite", "1 lata de leite condensado (395 g)"]'::jsonb, '["Derreta o açúcar até virar caramelo e junte a água quente.", "Espalhe a calda numa forma de 19 cm.", "Bata ovos, leite e leite condensado e coe sobre a forma.", "Cubra com alumínio e asse em banho-maria a 180 °C por cerca de 45 min (alguns fornos levam até 1h30; confira o ponto).", "Esfrie, leve à geladeira por 2 h e desenforme."]'::jsonb, false, 'rbKkgZpmcOI', null, 'https://www.receiteria.com.br/receita/pudim-de-leite-condensado/', null)
