insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('food-09', 'food', 'Coxinha', 'Difícil', '90 min', '25 unidades', null, '["Caldo: 1 peito de frango (800 g), 2 L de água, cebola, salsão, louro, cravo, limão", "Recheio: 280 g de frango desfiado, cebola, 2 tomates, alho, 2 colheres de manteiga, 2 de farinha", "Massa: 500 ml do caldo, 250 g de farinha de trigo, 3 colheres de manteiga", "Empanado: 2 claras e farinha de rosca", "Óleo para fritar"]'::jsonb, '["Cozinhe o frango com os aromáticos por uns 20 min; reserve o caldo e desfie.", "Refogue o recheio com tomate, temperos, frango e caldo e engrosse com farinha.", "Ferva o caldo com manteiga e sal, junte a farinha aos poucos e mexa até desgrudar; esfrie e sove.", "Abra bolinhas, recheie, modele e empane.", "Frite a cerca de 180 °C até dourar."]'::jsonb, false, 'M3b5ChhrZ7Q', null, 'https://www.receiteria.com.br/receita/coxinha/', null)
