insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('food-10', 'food', 'Pão de queijo', 'Médio', '80 min', '30 unidades', null, '["400 g de muçarela ralada", "500 g de polvilho azedo", "100 ml de leite e 100 ml de água", "3/4 de xícara de óleo", "1 colher de café cheia de sal", "2 ovos"]'::jsonb, '["Peneire o polvilho.", "Ferva leite, água, óleo e sal e despeje sobre o polvilho.", "Espere amornar e sove com ovos e queijo até desgrudar.", "Faça bolinhas com as mãos untadas.", "Asse a 180 °C por 30 min."]'::jsonb, false, 'PSJO8pZVqJ4', null, 'https://www.receiteria.com.br/receita/pao-de-queijo/', null)
