insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('health-01', 'health', 'Hidratação', 'Dica', null, null, 'Beber ao longo do dia é melhor do que de uma vez só. Frutas aquosas ajudam, mas não substituem a água.', '[]'::jsonb, '["Calcule uma meta diária de referência: cerca de 35 ml por kg de peso (≈2 L para 65 kg).", "Beba em pequenas quantidades ao longo do dia, não tudo de uma vez.", "Após suar muito, reponha o líquido perdido."]'::jsonb, false, null, 'https://www.youtube.com/minsaudebr', 'https://www.minhavida.com.br/materias/materia-8726', null)
