insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('health-02', 'health', 'Sono', 'Dica', null, null, 'Dormir mal causa cansaço, irritação e dificuldade de concentração. Se o problema persistir, procure um especialista em sono.', '[]'::jsonb, '["Faça uma rotina relaxante antes de deitar e desligue TV, celular e computador.", "Mantenha o quarto em temperatura amena e evite cafeína à noite.", "Pratique exercício durante o dia, de preferência de manhã."]'::jsonb, false, null, null, 'https://www.minhavida.com.br/materias/materia-12727', null)
