insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('health-03', 'health', 'Alimentação equilibrada', 'Dica', null, null, 'Variedade, alimentos naturais e regularidade valem mais que modismos.', '[]'::jsonb, '["Preencha metade do prato com salada e legumes; divida o resto entre carboidrato e proteína.", "Coma sem pressa e sem distrações; mastigue bem.", "Priorize alimentos naturais, inclua frutas e evite longos períodos sem comer."]'::jsonb, false, null, null, 'https://www.minhavida.com.br/alimentacao/tudo-sobre/20643-alimentacao-saudavel', null)
