insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('health-04', 'health', 'Atividade física', 'Dica', null, null, 'Qualquer movimento conta; crianças e adolescentes devem buscar cerca de 60 min por dia.', '[]'::jsonb, '["Adultos: 150 a 300 min por semana de atividade aeróbica moderada a vigorosa (OMS, 2020); divida em blocos, como 30 min em 5 dias.", "Se trabalha sentado, levante e se movimente com frequência.", "Idosos: inclua exercícios de força e equilíbrio."]'::jsonb, false, null, 'https://www.youtube.com/pahopin', 'https://www.paho.org/pt/noticias/26-11-2020-oms-lanca-novas-diretrizes-sobre-atividade-fisica-e-comportamento-sedentario', null)
