insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('health-05', 'health', 'Saúde mental e estresse', 'Dica', null, null, 'O estresse crônico afeta sono, pele e humor. Em casos intensos, procure psicólogo ou psiquiatra e não se automedique.', '[]'::jsonb, '["Caminhe, corra ou pedale cerca de 30 min por dia.", "Medite de 5 a 10 min, focando na respiração.", "Mantenha horários regulares de refeição e comemore pequenas conquistas."]'::jsonb, false, null, 'https://www.youtube.com/@einstein', 'https://www.einstein.br/n/vida-saudavel/como-diminuir-o-estresse', null)
