insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('health-06', 'health', 'Saúde do coração', 'Dica', null, null, 'Doenças cardiovasculares são a principal causa de morte no Brasil; a hipertensão é silenciosa, então vale medir a pressão.', '[]'::jsonb, '["Controle pressão, colesterol e diabetes com exames de rotina.", "Não fume e prefira óleos vegetais (azeite, canola) às gorduras saturadas.", "Coma mais vegetais, durma bem e controle o estresse."]'::jsonb, false, null, 'https://www.youtube.com/channel/UCYlaF2S8zWK7ntqw2vEP8qw', 'https://www.minhavida.com.br/saude/listas/11946-melhore-a-saude-do-seu-coracao-com-13-medidas', null)
