insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('health-07', 'health', 'Proteção solar', 'Dica', null, null, 'Os danos do sol se acumulam ao longo da vida. O filtro complementa sombra e roupas, não serve para ficar mais tempo no sol.', '[]'::jsonb, '["Evite o sol entre 10h e 16h e procure sombra, chapéu e óculos escuros.", "Aplique o filtro cerca de 30 min antes de sair.", "Reaplique a cada 2 horas e depois de nadar, suar ou se secar."]'::jsonb, false, null, 'https://www.youtube.com/user/tvinca', 'https://www.inca.gov.br/causas-e-prevencao/prevencao-e-fatores-de-risco/exposicao-solar/como-se-proteger-do-cancer-de-pele', null)
