insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('health-08', 'health', 'Lavar as mãos', 'Dica', null, null, 'Uma das medidas mais simples e eficazes contra infecções. Luvas não substituem a lavagem.', '[]'::jsonb, '["Molhe, ensaboe e esfregue por cerca de 15 s (palmas, dorso, entre os dedos, polegares, pontas).", "Enxágue bem e seque com papel toalha.", "Lave antes de comer e depois de tocar em algo sujo."]'::jsonb, false, null, null, 'https://fiocruz.br/biosseguranca/Bis/virtual%20tour/hipertextos/up1/lavagem_de_maos.html', null)
