insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('health-09', 'health', 'Postura', 'Dica', null, null, 'Pequenos ajustes diários previnem dor nas costas e problemas como hérnia de disco.', '[]'::jsonb, '["Sente com joelhos a 90°, pés apoiados, teclado na altura dos cotovelos e monitor a cerca de 40 cm.", "Pegue objetos do chão dobrando os joelhos, com as costas retas.", "Divida o peso de mochilas e sacolas entre os dois lados e alongue-se se ficar muito tempo parado."]'::jsonb, false, null, null, 'https://www.minhavida.com.br/materias/materia-9521', null)
