insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('health-10', 'health', 'Menos sal e menos açúcar', 'Dica', null, null, 'A OMS indica menos de 5 g de sal por dia e açúcares livres abaixo de 10% das calorias.', '[]'::jsonb, '["Leia rótulos e prefira versões com menos sódio e menos açúcar.", "Tempere com ervas, alho e cebola e limite conservas salgadas.", "Corte refrigerantes e sucos adoçados e reduza o açúcar das receitas aos poucos."]'::jsonb, false, null, 'https://www.youtube.com/user/tvinca', 'https://www.paho.org/en/topics/healthy-diet', null)
