insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('soap-01', 'soap', 'Sabonete glicerinado básico', 'Fácil', '30 min + 24–48 h', null, null, '["Cerca de 1 kg de base glicerinada", "30 a 40 ml de essência cosmética", "Corante solúvel em água", "Álcool de cereais em borrifador", "Opcional: 10 a 20 ml de óleo vegetal"]'::jsonb, '["Corte a base em cubos.", "Derreta em banho-maria ou no micro-ondas em pulsos curtos, sem ferver.", "Misture óleo, essência e corante aos poucos.", "Despeje nas formas e borrife álcool para tirar bolhas.", "Deixe endurecer e desenforme.", "Espere 24 a 48 h antes de usar ou embalar."]'::jsonb, false, '4oOkhl_msMc', null, 'https://catracalivre.com.br/criatividade/descobri-como-montar-meu-negocio-fazendo-sabonetes-artesanais-do-zero/', null)
