insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('soap-02', 'soap', 'Sabonete glicerinado de aveia', 'Fácil', '30 min + endurecer', null, null, '["250 g de glicerina transparente", "10 ml de mel", "1 colher de sopa de aveia em flocos finos", "10 ml de lauril líquido", "10 ml de extrato glicólico de aveia", "2 gotas de corante e essência a gosto", "Álcool de cereais em borrifador"]'::jsonb, '["Derreta a glicerina em pedaços em fogo médio.", "Junte essência, aveia, extrato, mel e corante e mexa.", "Despeje na forma.", "Borrife álcool se surgirem bolhas.", "Aguarde endurecer."]'::jsonb, false, null, null, 'https://www.tudogostoso.com.br/noticias/sabonete-natural-como-preparar-o-seu-em-casa-a1287.htm', null)
