insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('soap-03', 'soap', 'Sabonete de argila e aveia', 'Fácil', '30 min + endurecer', null, null, '["Base glicerinada vegetal", "1 a 2 colheres de chá de argila peneirada para cada 500 g de base", "1 a 3 colheres de sopa de aveia fina", "Óleo essencial (1% a 3% do peso total)", "Álcool de cereais"]'::jsonb, '["Derreta a base em cubos, sem ferver.", "Misture argila e aveia à base quente.", "Quando amornar, acrescente o óleo essencial.", "Despeje na forma e borrife álcool.", "Deixe endurecer por algumas horas."]'::jsonb, false, null, null, 'https://catracalivre.com.br/criatividade/5-passos-para-fazer-sabonete-artesanal-com-argila-e-aveia/', null)
