insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('soap-04', 'soap', 'Sabonete de ervas secas', 'Fácil', '40 min + 24 h', null, null, '["Base glicerinada", "Óleos, essências e extratos (proporções conforme a embalagem da base)", "Corante opcional", "Ervas, flores ou frutas secas"]'::jsonb, '["Corte e derreta a glicerina em fogo médio, mexendo.", "Desligue e adicione os óleos.", "Deixe esfriar um pouco e junte essências e extratos.", "Forre a forma de silicone com as ervas e despeje a mistura.", "Cubra com pano limpo e deixe 24 h em local seco.", "Desenforme e embale."]'::jsonb, false, 'oGFQYnl85lw', null, 'https://www.nuvemshop.com.br/blog/como-fazer-sabonete-artesanal-para-vender/', 'Vídeo pode tratar de glicerina em geral; confira antes de publicar.')
