insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('soap-05', 'soap', 'Sabão em barra de óleo de cozinha usado', 'Médio', '40 min + 20–45 dias de cura', null, null, '["1 kg de óleo usado e coado", "140 ml de água", "135 g de soda cáustica em escamas (acima de 95%)", "Opcional: 25 ml de álcool, 30 g de essência, 10 g de alecrim em pó"]'::jsonb, '["Vista os EPIs e aqueça a água a cerca de 40 °C.", "Dissolva a soda na água aos poucos e aqueça o óleo coado a cerca de 40 °C.", "Despeje a solução de soda no óleo devagar, mexendo sempre.", "Mexa por 20 a 30 min, até ficar como leite condensado; se estiver líquido demais, junte o álcool aos poucos.", "Misture a essência e despeje em formas que não sejam de alumínio.", "Deixe curar de 20 a 45 dias em local fresco e escuro; depois desenforme e corte."]'::jsonb, true, '26CyIo8nr4Q', null, 'https://www.ecycle.com.br/sabao-caseiro/', null)
