insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('soap-06', 'soap', 'Sabão aromático de lavanda', 'Médio', '40 min + cura', null, null, '["1 litro de óleo vegetal usado e coado", "130 g de soda cáustica", "200 ml de água", "15 a 20 gotas de óleo essencial de lavanda"]'::jsonb, '["Dissolva a soda na água em local arejado e deixe esfriar.", "Junte ao óleo coado, mexendo devagar até engrossar.", "Adicione o óleo essencial.", "Despeje nas formas e deixe 24 h, protegido da umidade.", "Deixe curar por 20 a 45 dias (a fonte cita 7 dias, mas outras fontes recomendam cura mais longa).", "Guarde fechado, em local seco e sem sol."]'::jsonb, true, null, null, 'https://catracalivre.com.br/saude-bem-estar/como-fazer-sabao-caseiro-perfumado-com-cheiro-de-lavanda-para-usar-na-casa-toda/', null)
