insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('soap-07', 'soap', 'Sabonete de processo a frio (coco, oliva e outro óleo)', 'Avançado', '1 h + 24–48 h + ~4 semanas de cura', null, null, '["Óleo de coco, azeite e um terceiro óleo (amêndoa ou girassol)", "Soda cáustica e água", "Ervas e óleos essenciais (opcional)", "IMPORTANTE: calcule as quantidades por PESO em uma calculadora de saponificação antes de fazer; a fonte original usa medidas em volume, que não são confiáveis."]'::jsonb, '["Dissolva a soda na água e deixe esfriar até 35–40 °C.", "Misture e aqueça os óleos a cerca de 45 °C e espere chegar a 35–40 °C.", "Junte a soda aos óleos aos poucos e mexa cerca de 5 min, até clarear e engrossar.", "Adicione ervas ou óleos essenciais.", "Coloque na forma, cubra com filme e agasalhe com toalha.", "Após 24 h desenforme e corte; seque por cerca de 4 semanas, virando as peças."]'::jsonb, true, null, null, 'https://www.e-konomista.pt/como-fazer-sabonete-artesanal/', null)
