insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('soap-08', 'soap', 'Sabão líquido para roupas', 'Fácil', '30 min + 1 h', null, null, '["200 g de sabão em barra", "3 colheres de sopa de bicarbonato", "3 litros de água", "10 gotas de óleo essencial"]'::jsonb, '["Rale o sabão.", "Ferva 1 litro de água, junte as raspas e mexa até dissolver.", "Adicione o bicarbonato e deixe descansar 1 h.", "Junte 1 litro de água morna e coe.", "Acrescente o óleo essencial e mais 1 litro de água fria.", "Deixe descansar 20 min e divida em potes; use cerca de 200 ml por carga."]'::jsonb, false, '26CyIo8nr4Q', null, 'https://www.ecycle.com.br/como-fazer-sabao-liquido/', null)
