insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('soap-09', 'soap', 'Sabão em pó caseiro', 'Fácil', '20 min + 2 h de secagem', null, null, '["2 barras de sabão glicerinado", "1 barra de sabão de coco", "1 sabonete", "3 colheres de sopa de bicarbonato", "1 colher de sopa de sal fino"]'::jsonb, '["Rale todas as barras em uma bacia.", "Misture bicarbonato e sal.", "Espalhe em uma forma grande e seque ao sol por cerca de 2 h.", "Bata aos poucos no liquidificador até virar pó fino.", "Guarde em pote com tampa."]'::jsonb, false, 'cq2Yl_Ok2iM', null, 'https://receitatodahora.com.br/receita-de-sabao-em-po-caseiro-que-rende-muito-para-voce-economizar-tempo-e-dinheiro/', null)
