insert into public.items (id, category, title, level, "time", servings, summary, ingredients, steps, safety, video_id, channel_url, source_url, note) values ('soap-10', 'soap', 'Sabão em barra sem soda', 'Fácil', '40 min + 1 dia', null, null, '["4 barras de sabão glicerinado de 180 g raladas", "500 g de açúcar", "1 litro de água fervente", "700 ml de álcool etílico", "1 colher de sopa de bicarbonato", "1 colher de sopa de sal", "100 ml de detergente"]'::jsonb, '["Derreta as raspas com o açúcar e a água fervente em fogo baixo ou banho-maria.", "Apague o fogo e adicione o álcool aos poucos, longe do fogo (é inflamável).", "Incorpore bicarbonato, sal e detergente.", "Despeje em forminhas e borrife álcool para tirar a espuma.", "Deixe endurecer cerca de 1 dia.", "Desenforme e embrulhe em filme."]'::jsonb, false, null, null, 'https://catracalivre.com.br/noticias/como-fazer-sabao-caseiro-sem-soda-sem-oleo-e-que-fica-durinho/', null)
